const input = $input.first().json.chatInput || $input.first().json.input || '';
return [{ 
  json: {
    niche: 'Personal Finance India',
    competitors: '@pranjal.kamra, @warikoo, @sharan_hegde, @the_dailydecode',
    topic: input,
    timestamp: new Date().toISOString()
  }
}];

try {
  const data = $input.first().json;
  const topic = $('Setup Input').first().json.topic;

  // Get all previous search results from input chain
  let competitorResults = 'No competitor data';
  let trendsResults = 'No trends data';
  let youtubeResults = 'No YouTube data';

  try {
    const comp = $('Search Competitors').first().json;
    if (comp && comp.results) {
      competitorResults = comp.results
        .filter(r => r.title && r.content)
        .map(r => 'TITLE: ' + r.title + '\nCONTENT: ' + r.content)
        .join('\n\n');
    }
  } catch(e1) {
    competitorResults = 'Competitor search error: ' + e1.message;
  }

  try {
    const trends = $('Search YouTube Trends').first().json;
    if (trends && trends.results) {
      trendsResults = trends.results
        .filter(r => r.title && r.content)
        .map(r => 'TITLE: ' + r.title + '\nCONTENT: ' + r.content)
        .join('\n\n');
    }
  } catch(e2) {
    trendsResults = 'Trends search error: ' + e2.message;
  }

  try {
    const yt = $('Search YouTube Trends').first().json;
    if (yt && yt.results) {
      youtubeResults = yt.results
        .filter(r => r.title && r.content)
        .map(r => 'TITLE: ' + r.title + '\nCONTENT: ' + r.content)
        .join('\n\n');
    }
  } catch(e3) {
    youtubeResults = 'YouTube search error: ' + e3.message;
  }

return [{
  json: {
    topic: topic,
    competitor_data: competitorResults,
    trends_data: trendsResults,
    youtube_data: youtubeResults,
    instagram_summary: competitorResults.substring(0, 500),
    youtube_summary: youtubeResults.substring(0, 500),
    combined_context:
      'INSTAGRAM DATA:\n' + competitorResults +
      '\n\nGOOGLE TRENDS:\n' + trendsResults +
      '\n\nYOUTUBE DATA:\n' + youtubeResults
  }
}];

} catch(e) {
  return [{ json: { error: e.message } }];
}

const response = $input.first().json;

let strategy;

if (response.choices && response.choices[0]) {
  strategy = response.choices[0].message.content;
} else if (response.strategy_output) {
  strategy = response.strategy_output;
} else {
  strategy = JSON.stringify(response);
}

return [{
  json: {
    strategy_output: strategy,
    topic: $('Merge Research').first().json.topic,
    combined_context: $('Merge Research').first().json.combined_context,
    instagram_summary: $('Merge Research').first().json.instagram_summary,
    youtube_summary: $('Merge Research').first().json.youtube_summary
  }
}];

try {
  const data = $input.first().json;

  let scripts;
  if (data.scripts_output) {
    scripts = data.scripts_output;
  } else if (data.choices && data.choices[0]) {
    scripts = data.choices[0].message.content;
  } else {
    scripts = JSON.stringify(data);
  }

  const strategy = $('Extract Strategy').first().json.strategy_output || '';
  const topic = $('Extract Strategy').first().json.topic || '';
  const instagram_summary = $('Extract Strategy').first().json.instagram_summary || '';
  const youtube_summary = $('Extract Strategy').first().json.youtube_summary || '';

  return [{
    json: {
      scripts_output: scripts,
      strategy_output: strategy,
      topic: topic,
      instagram_summary: instagram_summary,
      youtube_summary: youtube_summary
    }
  }];

} catch(e) {
  return [{
    json: {
      error: e.message,
      scripts_output: 'Error in Extract Scripts: ' + e.message,
      strategy_output: '',
      topic: '',
      instagram_summary: '',
      youtube_summary: ''
    }
  }];
}

