const openRouterKey = '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'; // get from openrouter.ai
const data = $input.first().json;

const systemPrompt = `You are Agent 1 - a Finance Content Strategist for INDIAN social media audience.

You have access to data from TWO platforms:
1. INSTAGRAM data - what @pranjal.kamra @warikoo @sharan_hegde are posting and what is performing
2. YOUTUBE data - what finance videos are trending in India right now

YOUR JOB:
Cross reference BOTH platforms to find:
- Topics trending on BOTH YouTube AND Instagram = highest priority ideas
- Topics viral on YouTube but NOT yet on Instagram = content opportunity
- Angles competitors are missing = content gap nobody has covered

Output TOP 5 content ideas with EXACTLY this format:

1. TOPIC: [topic name]
   INSTAGRAM TREND: [what competitors are doing on Instagram right now]
   YOUTUBE TREND: [what is trending on YouTube India with view count if available]
   CONTENT GAP: [what angle nobody has covered yet]
   HOOK ANGLE: [shocking opening line with Indian number or bold claim]
   WHY NOW: [why this topic is hot RIGHT NOW on both platforms]
   ENGAGEMENT POTENTIAL: [Very High or High + specific reason]

INDIA SPECIFIC RULES:
- Use Indian currency INR and Rupees not dollars
- Reference Indian context EMIs FDs PPF SIP Mutual Funds LIC
- Use Indian salary ranges 30k/month 50k/month 1LPA 5LPA 10LPA
- Reference Indian problems high rent Mumbai Bangalore inflation job market
- Mention Indian platforms Zerodha Groww PhonePe Paytm
- Use Hinglish phrases naturally yaar bhai sach mein
- Reference Indian life stages board exams engineering MBA rat race IT job marriage pressure EMI trap

PLATFORM SPECIFIC RULES:
- For Instagram: focus on what stops scroll in 3 seconds
- For YouTube: focus on what gets clicks and watch time
- Always find the CROSS PLATFORM opportunity
- Prioritize topics that can go viral on BOTH platforms simultaneously

COMPETITOR ANALYSIS RULES:
- Study what @pranjal.kamra posts that gets most engagement
- Study what @warikoo angle is different from others
- Study what @sharan_hegde does that feels native to platform
- Find the GAP between what they cover and what audience wants`;
const maxChars = 3000;
const trimmedContext = data.combined_context 
  ? data.combined_context.substring(0, maxChars) + '...[trimmed]'
  : 'No research data available';
const userPrompt = `Topic: ${data.topic}\n\nResearch Data:\n${trimmedContext}`;

const response = await this.helpers.request({
  method: 'POST',
  url: 'https://openrouter.ai/api/v1/chat/completions',
  headers: {
    'Authorization': `Bearer ${openRouterKey}`,
    'Content-Type': 'application/json',
    'HTTP-Referer': 'https://n8n.io',
    'X-Title': 'Finance Content Agent'
  },
  body: JSON.stringify({
    model:'openrouter/free',
    temperature: 0.7,
    max_tokens: 2000,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ]
  })
});

let result;
try {
  result = typeof response === 'string' ? JSON.parse(response) : response;
} catch(e) {
  return [{ json: { error: 'Parse failed: ' + e.message, raw: response } }];
}

if (!result.choices || !result.choices[0]) {
  return [{ json: { error: 'No choices in response', raw: JSON.stringify(result) } }];
}

const strategy = result.choices[0].message.content;

return [{
  json: {
    strategy_output: strategy,
    topic: data.topic,
    combined_context: data.combined_context,
    instagram_summary: data.instagram_summary,
    youtube_summary: data.youtube_summary,
    model_used: 'google/gemini-2.0-flash via OpenRouter'
  }
}];

